function ar_replace(string $path, ?string $beforeHash, string $body, int $mode): void {
    $current = is_file($path) ? hash_file('sha256',$path) : null;
    ar_assert(!is_link($path) && $current === $beforeHash,'target_changed_before_write');
    $temp = $path . '.acc009-' . bin2hex(random_bytes(8)); $h = fopen($temp,'x');
    ar_assert($h !== false,'target_temp_failed');
    try {
        ar_assert(fwrite($h,$body) === strlen($body) && fflush($h),'target_temp_write_failed');
        ar_assert(fclose($h),'target_temp_close_failed'); $h = null;
        ar_assert(chmod($temp,$mode),'target_temp_mode_failed');
        ar_assert(!is_link($path) && (is_file($path)?hash_file('sha256',$path):null) === $beforeHash,'target_changed_before_rename');
        ar_assert(rename($temp,$path),'target_rename_failed');
    } finally { if (is_resource($h)) fclose($h); if (is_file($temp)) unlink($temp); }
}

